/* Accessing 2D Array using Pointer to Array */
int matrix[3][4];
typedef int (*RowPtr)[4];
RowPtr row_ptr = matrix;
int element = (*(row_ptr + 1))[2]; // matrix[1][2]

/* 3D Array Pointer Arithmetic */
int cube[2][3][4];
int *base = (int *)cube;
size_t D1 = 3 * 4;
size_t D2 = 4;
// Access cube[i][j][k]
int i=1, j=2, k=3;
int value = base[i * D1 + j * D2 + k];

/* Pointer to Function returning Pointer */
int (*(*pf_ptr)())[10]; // Declares pf_ptr

/* Void Pointer Traversal (Manual Type Casting) */
void *v_ptr = base;
int data = *((int *)v_ptr + 5);

/* Array decay to pointer and arithmetic */
int arr[] = {10, 20, 30};
int *p = arr;
int element = *(p + 2); // arr[2]

/* Pointer Difference */
int arr_end = *(p + 3); // (Hypothetical boundary)
ptrdiff_t diff = &arr_end - arr; // 3
